package info.piepgras.gridracer

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import info.piepgras.gridracer.engine.AppSettings
import kotlinx.coroutines.flow.StateFlow

/** Every sound effect the app plays; the WAVs are generated by `scripts/generate_sounds.py`. */
enum class Sound { CLICK, CRASH, FINISH, MOTOR, PISTOL }

/** Something that can play a [Sound]; [SoundManager] is the real one. */
fun interface SoundEffects {
    /** Plays [sound], unless sound effects are switched off. */
    fun play(sound: Sound)
}

/** Wraps [SoundPool] for short, low-latency sound effects, gated live by the Settings sound toggle. */
class SoundManager(context: Context, private val settings: StateFlow<AppSettings>) : SoundEffects {

    private val soundPool = SoundPool.Builder()
        .setMaxStreams(4)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build(),
        )
        .build()

    private val soundIds: Map<Sound, Int> = mapOf(
        Sound.CLICK to soundPool.load(context, R.raw.sfx_button_click, 1),
        Sound.CRASH to soundPool.load(context, R.raw.sfx_crash, 1),
        Sound.FINISH to soundPool.load(context, R.raw.sfx_finish_cheer, 1),
        Sound.MOTOR to soundPool.load(context, R.raw.sfx_motor_hum, 1),
        Sound.PISTOL to soundPool.load(context, R.raw.sfx_starting_pistol, 1),
    )

    override fun play(sound: Sound) {
        if (!settings.value.soundEffectsEnabled) return
        val id = soundIds[sound] ?: return
        soundPool.play(id, 1f, 1f, 0, 0, 1f)
    }

    /** Frees the sound pool. The instance cannot play anything afterwards. */
    fun release() {
        soundPool.release()
    }
}
